eTypeDef huart1;extern DMA_HandleTypeDef hdma_usart1_rx;extern DMA_HandleTypeDef hdma_usart1_tx;/* USER CODE BEGIN Private defines */ #define BUFFER_SIZE 100 extern volatile uint8_t rx_len ; //接收一帧数据的长度extern volatile uint8_t recv_end_flag; //一帧数据接收完成标志extern uint8_t rx_buffer[100]; //接收数据缓存数组 main.c 12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152/*********************************************************************************************************** 函 数 名: DMA_Usart_Send* 功能说明: 串口发送功能函数* 形 参: buf，len* 返 回 值: 无**********************************************************************************************************/void DMA_Usart_Send(uint8_t *buf,uint8_t len)//串口发送封装&#123; if(HAL_UART_Transmit_DMA(&amp;huart1, buf,len)!= HAL_OK) //判断是否发送正常，如果出现异常则进入异常中断函数 &#123; Error_Handler(); &#125;&#125;/*********************************************************************************************************** 函 数 名: DMA_Usart1_Read* 功能说明: 串口接收功能函数* 形 参: Data,len* 返 回 值: 无**********************************************************************************************************/void DMA_Usart1_Read(uint8_t *Data,uint8_t len)//串口接收封装&#123; HAL_UART_Receive_DMA(&amp;huart1,Data,len);//重新打开DMA接收&#125; while (1) &#123; /* USER CODE END WHILE */ /* USER CODE BEGIN 3 */ if(recv_end_flag == 1) //接收完成标志 &#123; DMA_Usart_Send(rx_buffer, rx_len); rx_len = 0;//清除计数 recv_end_flag = 0;//清除接收结束标志位// for(uint8_t i=0;i&lt;rx_len;i++)// &#123;// rx_buffer[i]=0;//清接收缓存// &#125; memset(rx_buffer,0,rx_len); &#125; HAL_UART_Receive_DMA(&amp;huart1,rx_buffer,BUFFER_SIZE);//重新打开DMA接收&#125; stm32f1xx_it.c中 123456789101112131415161718192021222324#include &quot;usart.h&quot;void USART1_IRQHandler(void)&#123; uint32_t tmp_flag = 0; uint32_t temp; tmp_flag =__HAL_UART_GET_FLAG(&amp;huart1,UART_FLAG_IDLE); //获取IDLE标志位 if((tmp_flag != RESET))//idle标志被置位 &#123; __HAL_UART_CLEAR_IDLEFLAG(&amp;huart1);//清除标志位 //temp = huart1.Instance-&gt;SR; //清除状态寄存器SR,读取SR寄存器可以实现清除SR寄存器的功能 //temp = huart1.Instance-&gt;DR; //读取数据寄存器中的数据 //这两句和上面那句等效 HAL_UART_DMAStop(&amp;huart1); // temp = __HAL_DMA_GET_COUNTER(&amp;hdma_usart1_rx);// 获取DMA中未传输的数据个数 //temp = hdma_usart1_rx.Instance-&gt;NDTR;//读取NDTR寄存器 获取DMA中未传输的数据个数， //这句和上面那句等效 rx_len = BUFFER_SIZE - temp; //总计数减去未传输的数据个数，得到已经接收的数据个数 recv_end_flag = 1; // 接受完成标志位置1 &#125; HAL_UART_IRQHandler(&amp;huart1);&#125;

[TOC] 通信接口了解 通信的目的︰将一个设备的数据传送到另一个设备，扩展硬件系统 通信协议︰制定通信的规则，通信双方按照协议规则进行数据收发 STM32里边有下表这么多的通讯协议（表格仅列一些常看的典型参数） 名称 引脚 传输模式 时钟 电平 设备 USART TX、RX 全双工 同&#x2F;异步 单端 点对点 I2C SCL、SDA 半双工 同步 单端 多设备 SPI SCLK、MOSI、MISO、CS 全双工 同步 单端 多设备 CAN CAN_H、CAN_L 半双工 异步 差分 多设备 USB DP、DM 半双工 异步 差分 点对点 同步需要时钟线来保证传输数据不冲突。 【注】全双工：打电话。 半双工：对讲机。 单工：广播。 一、USART通信1.1 串口通讯协议通讯时钟：同步靠时钟线，异步靠比特率（用的多） 1.1.1 简介串口是一种应用十分广泛的通讯接口，串口成本低、容易使用、通信线路简单，可实现两个设备的互相通信。单片机的串口可以使单片机与单片机、单片机与电脑、单片机与各式各样的模块互相通信，极大地扩展了单片机的应用范围，增强了单片机系统的硬件实力。 1.1.2硬件电路 简单双向串口通信有两根通信线(发送端TX和接收端RX) TX与RX要交叉连接 当只需单向的数据传输时，可以只接一根通信线 当电平标准不一致时，需要加电平转换芯片 因为TX&#x2F;RX的高低电平是相对于GND来说的，所以这三根都是通讯线，双向通信必须要连接的。VCC则看设备双方是否都有供电而考虑。 【电平标准】 电平标准是数据1和数据0的表达方式，是传输线缆中人为规定的电压与数据的对应关系，串口常用的电平标准有如下三种︰ TTL电平：+3.3V或+5V表示1，OV表示0 RS232电平（大机器）：-3-15V表示1，+3+15V表示0 RS485电平：两线压差+2+6V表示1，-2-6V表示0（差分信号）抗干扰（可达上千米） 1.1.3串口参数及时序 波特率∶串口通信的速率（决定每隔多久发送一位） 起始位︰标志一个数据帧的开始，固定为低电平 数据位︰数据帧的有效载荷，1为高电平。0为低电平，低位先行 校验位︰用于数据验证，根据数据位计算得来 停止位︰用于数据帧间隔，固定为高电平 校验方式：****奇偶校验、和校验、CRC校验、LRC校验….. 【时序波形】 1.2USART外设1.2.1 USART简介 UART：universal asynchronous receiver and transmitter通用异步收&#x2F;发器 USART： (Universal Synchronous&#x2F;Asynchronous Receiver&#x2F;Transmitter）通用同步&#x2F;异步收发器 注：这里的同步模式，多了一个仅支持输出的时钟，是兼容别的协议或者特殊用途而设计；不支持两个USART之间进行同步通信。因此我们主要还是学习异步通信。 USART是STM32内部集成的硬件外设，可根据数据寄存器的一个字节数据自动生成数据帧时序，从TX引脚发送出去，也可自动接收RX引脚的数据帧时序，拼接为一个字节数据，存放在数据寄存器里。 自带波特率发生器，最高达4.5Mbits&#x2F;s 可配置参数：数据位长度(8&#x2F;9)、停止位长度(0.5&#x2F;1&#x2F;1.5&#x2F;2)，即间隔 可选校验位（无校验&#x2F;奇校验&#x2F;偶校验) 支持同步模式、硬件流控制、DMA、智能卡、IrDA（红外通信）、LIN（局域网通信协议） 【硬件流控制】如果数据发送得过快来不及接收，那么就可以通过这个来控制USART处于可收发的状态，一般不用。 STM32F103C8T6 USART资源：USART1、USART2、USART3 注意：开启时钟时候注意挂载的总线 1.2.2 USART框图一开始比较乱，可以先忽略图中长条状寄存器每一位的描述。 主要关注TX&#x2F;RX引脚，一个发送一个接收。 DR寄存器：占用同一个地址，但是硬件上是两个寄存器，TDR发送数据寄存器、RDR接收数据寄存器。 移位寄存器：一个发送，从寄存器转移（低位往高位发送）；一个接收，转移到寄存器（高位往低位接收）。通过标志位进行判断数据接收&#x2F;发送完成。 发送接收器控制： 硬件数据流控：了解 SCK输出：用于兼容其他协议。 唤醒单元：（了解）串口实现挂载多设备，可以给串口分配一个地址，当发送制定地址时，此设备唤醒开始工作。当你发送别的设备地址时，别的设备就唤醒工作，没收到的就保持沉默。 中断申请位：就是状态寄存器这里的各种标志位，标志位的TXE发送寄存器空，RXNE接收寄存器非空，是判断发送和接收状态的必要标志位。（其他可以看手册） USART中断控制：配置中断是不是能通向NVIC 波特率发生器：分频器，APB时钟进行分频，得到发送和接收移位的时钟。 1.2.3 USART基本结构发送接收引脚是GPIO的复用输出，开发时候，如果硬工没给你画好，则需要注意引脚的划分，避免冲突。 发送接收移位寄存器硬件上看着有四个，但实际软件成眠只有一个DR寄存器供我们读写。 1.3 数据帧解析1.3.1 字长设置 有效载荷保持1字节，会比较的…使强迫症情绪稳定。 1.3.2 配置停止位不常用，随便配 1.3.3 USART输入数据策略起始位侦测：数据采样位置对齐正中间 数据采样流程：可以对噪声进行判断，三次采样规则（全一致，采样电平不同，则按次数最多的考虑），但凡有不一致的就置位NE，代表有噪声。 1.3.4 波特率发生器发送器和接收器的波特率由波特率寄存器BRR里的DIV确定 计算公式：波特率&#x3D; fPCLkK2&#x2F;1&#x2F;(16*DIV) 自行理解。 1.3.5CH340模块 CH340的供电跳线帽最好不要拿掉，拿掉也没事，但只有3.3V供电。通讯电平不一致没啥关系，模块的供电正确就行了。其他是LED指示灯。 【案例】串口发送+接收① 使能相关时钟：开启 USART1、GPIOA、AFIO 的时钟，USART1 和 GPIOA 属于 APB2 总线： 12345#include &quot;stm32f10x.h&quot;#include &lt;string.h&gt;void USART1_Init(void) &#123; RCC_APB2PeriphClockCmd(RCC_APB2Periph_USART1 | RCC_APB2Periph_GPIOA | RCC_APB2Periph_AFIO, ENABLE); ② 配置串口 GPIO 引脚：PA9（TX）为复用推挽输出，PA10（RX）为浮空输入： 1234567891011GPIO_InitTypeDef GPIO_InitStructure;// TX引脚（PA9）GPIO_InitStructure.GPIO_Pin = GPIO_Pin_9;GPIO_InitStructure.GPIO_Mode = GPIO_Mode_AF_PP;GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;GPIO_Init(GPIOA, &amp;GPIO_InitStructure);// RX引脚（PA10）GPIO_InitStructure.GPIO_Pin = GPIO_Pin_10;GPIO_InitStructure.GPIO_Mode = GPIO_Mode_IN_FLOATING;GPIO_Init(GPIOA, &amp;GPIO_InitStructure); ③ 初始化 USART1 核心参数：设置波特率 115200、8 位数据、1 位停止位、无校验： 12345678USART_InitTypeDef USART_InitStructure;USART_InitStructure.USART_BaudRate = 115200;USART_InitStructure.USART_WordLength = USART_WordLength_8b;USART_InitStructure.USART_StopBits = USART_StopBits_1;USART_InitStructure.USART_Parity = USART_Parity_No;USART_InitStructure.USART_HardwareFlowControl = USART_HardwareFlowControl_None;USART_InitStructure.USART_Mode = USART_Mode_Tx | USART_Mode_Rx;USART_Init(USART1, &amp;USART_InitStructure); ④ 配置串口接收中断：配置 NVIC 优先级，使能 USART1 接收中断： 12345678910 NVIC_InitTypeDef NVIC_InitStructure; NVIC_InitStructure.NVIC_IRQChannel = USART1_IRQn; NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 1; NVIC_InitStructure.NVIC_IRQChannelSubPriority = 1; NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE; NVIC_Init(&amp;NVIC_InitStructure); USART_ITConfig(USART1, USART_IT_RXNE, ENABLE); USART_Cmd(USART1, ENABLE);&#125; ⑤ 实现串口发送函数：包括单个字节发送和字符串发送： 123456789101112void USART1_SendByte(uint8_t byte) &#123; while (USART_GetFlagStatus(USART1, USART_FLAG_TXE) == RESET); USART_SendData(USART1, byte);&#125;void USART1_SendString(uint8_t *str) &#123; uint16_t i = 0; while (str[i] != &#x27;\0&#x27;) &#123; USART1_SendByte(str[i]); i++; &#125;&#125; ⑥ 定义接收缓冲区和标志：用于存储接收数据和标记接收完成： 123uint8_t rx_buf[100];uint16_t rx_len = 0;uint8_t rx_flag = 0; // 接收完成标志（如收到回车符置1） ⑦ 编写串口中断服务函数：接收数据并判断结束条件： 12345678910111213141516void USART1_IRQHandler(void) &#123; if (USART_GetITStatus(USART1, USART_IT_RXNE) != RESET) &#123; uint8_t data = USART_ReceiveData(USART1); // 读取接收数据 // 存储数据到缓冲区，遇到回车符结束 if (rx_len &lt; 99 &amp;&amp; data != &#x27;&#x27;) &#123; rx_buf[rx_len++] = data; &#125; else &#123; rx_buf[rx_len] = &#x27;\0&#x27;; // 字符串结尾 rx_flag = 1; // 置接收完成标志 rx_len = 0; // 重置长度 &#125; USART_ClearITPendingBit(USART1, USART_IT_RXNE); &#125;&#125; ⑧ 在 main 函数中使用：发送测试数据，接收并回传数据： 12345678910111213141516171819int main(void) &#123; USART1_Init(); while (1) &#123; // 发送示例 USART1_SendString((uint8_t*)&quot;Hello World!
&quot;); // 接收处理 if (rx_flag == 1) &#123; USART1_SendString((uint8_t*)&quot;Received: &quot;); USART1_SendString(rx_buf); USART1_SendString((uint8_t*)&quot;
&quot;); rx_flag = 0; // 清除标志 &#125; // 延时 for (uint32_t i = 0; i &lt; 7200000; i++); &#125;&#125; 1.4 USART串口数据包1.4.1 HEX数据包数据包的作用？ 把一个个单独的数据打包起来，方便进行多字节通讯。打包的方式可以是自己设定，也可以是别开发者规定，即自拟通讯协议。根据协议规则（掐包头包尾）在连续不断接收的数据流中提取出需要的数据。 固定包长，含包头包尾（课程自拟） 可变包长，含包头包尾 如果数据位和包头包尾****重复怎么办？ 基础解决方案：①限制载荷数据的范围，在范围内即为正常数据。②尽量使用固定包长，即规定有效数据长度，对齐后用于接收后判断提取。③增加包头包尾的字节数量，多次判断，好确定是包头。….（工作中还有其他方式，可自行学习） 固定包长和可变包长如何选择？ 如果载荷数据会跟包头包尾重复，则固定长度比较合适。不重复就选可变。 1.4.2 文本数据包说明：HEX数据包本身就是以原始的字节数据本身呈现的字节流，而文本数据包里面，每个字节就多了一层编码和译码，最终呈现出来的就是文本格式。虽然背后还是字节数据，这就存在独特的字符，可以有效避免数据载荷和包头包尾重复的问题。 缺点：解析效率低，需要根据使用场景来使用。 固定包长，含包头包尾 可变包长，含包头包尾 1.4.3 数据包接收发送比较简单，接收比较复杂，因此复杂内容较值得讨论。接收逻辑通用。 笔者说明：使用状态机用于表示标志位再接受过程中的状态变化，用于判断不同情况，根据这些状态执行不同的操作代码。比如开始接收到一个字节，进入中断，此时状态还没有接收到包头&#x3D;0，就需要先判断是不是包头，而不判断其他。就这样一个字节一个字节的判断，终于拿到了完整的包头，状态就发生了改变&#x3D;1，这时候再接收到一个字节，直接就保存接收后面固定长度的内容， 【案例】串口收发HEX数据包① 使能相关时钟：开启 USART1、GPIOA、AFIO 时钟： 1234567#include &quot;stm32f10x.h&quot;#include &lt;string.h&gt;#define HEX_BUF_SIZE 50 // HEX数据包最大长度void USART1_Init(uint32_t baudrate) &#123; RCC_APB2PeriphClockCmd(RCC_APB2Periph_USART1 | RCC_APB2Periph_GPIOA | RCC_APB2Periph_AFIO, ENABLE); ② 配置串口 GPIO：PA9（TX）复用推挽，PA10（RX）浮空输入： 1234567891011GPIO_InitTypeDef GPIO_InitStructure;// TX引脚（PA9）GPIO_InitStructure.GPIO_Pin = GPIO_Pin_9;GPIO_InitStructure.GPIO_Mode = GPIO_Mode_AF_PP;GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;GPIO_Init(GPIOA, &amp;GPIO_InitStructure);// RX引脚（PA10）GPIO_InitStructure.GPIO_Pin = GPIO_Pin_10;GPIO_InitStructure.GPIO_Mode = GPIO_Mode_IN_FLOATING;GPIO_Init(GPIOA, &amp;GPIO_InitStructure); ③ 初始化 USART 参数：设置波特率、无校验、8 位数据： 12345678USART_InitTypeDef USART_InitStructure;USART_InitStructure.USART_BaudRate = baudrate;USART_InitStructure.USART_WordLength = USART_WordLength_8b;USART_InitStructure.USART_StopBits = USART_StopBits_1;USART_InitStructure.USART_Parity = USART_Parity_No;USART_InitStructure.USART_HardwareFlowControl = USART_HardwareFlowControl_None;USART_InitStructure.USART_Mode = USART_Mode_Tx | USART_Mode_Rx;USART_Init(USART1, &amp;USART_InitStructure); ④ 配置接收中断：使能 USART1 接收中断及 NVIC： 12345678910 NVIC_InitTypeDef NVIC_InitStructure; NVIC_InitStructure.NVIC_IRQChannel = USART1_IRQn; NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 1; NVIC_InitStructure.NVIC_IRQChannelSubPriority = 1; NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE; NVIC_Init(&amp;NVIC_InitStructure); USART_ITConfig(USART1, USART_IT_RXNE, ENABLE); // 使能接收中断 USART_Cmd(USART1, ENABLE);&#125; ⑤ 实现 HEX 发送函数：发送单字节 HEX 数据： 12345678910111213141516171819202122232425// 发送单个HEX字节（如0xAB → 发送0x41 0x42，即字符&#x27;A&#x27;&#x27;B&#x27;）void USART1_SendHexByte(uint8_t hex) &#123; uint8_t high = (hex &gt;&gt; 4) &amp; 0x0F; // 高4位 uint8_t low = hex &amp; 0x0F; // 低4位 // 发送高4位（0-9→&#x27;0&#x27;-&#x27;9&#x27;，A-F→&#x27;A&#x27;-&#x27;F&#x27;） high += (high &lt; 10) ? &#x27;0&#x27; : (&#x27;A&#x27; - 10); while (USART_GetFlagStatus(USART1, USART_FLAG_TXE) == RESET); USART_SendData(USART1, high); // 发送低4位 low += (low &lt; 10) ? &#x27;0&#x27; : (&#x27;A&#x27; - 10); while (USART_GetFlagStatus(USART1, USART_FLAG_TXE) == RESET); USART_SendData(USART1, low);&#125;// 发送HEX数据包（带前缀0x和后缀空格，如0xAB 0xCD）void USART1_SendHexPacket(uint8_t *buf, uint16_t len) &#123; for (uint16_t i = 0; i &lt; len; i++) &#123; USART1_SendString((uint8_t*)&quot;0x&quot;); USART1_SendHexByte(buf[i]); USART1_SendByte(&#x27; &#x27;); &#125; USART1_SendString((uint8_t*)&quot;
&quot;);&#125; ⑥ 定义 HEX 接收缓冲区及状态变量： 1234uint8_t hex_rx_buf[HEX_BUF_SIZE]; // 存储解析后的HEX数据uint8_t hex_rx_len = 0; // 接收长度uint8_t rx_state = 0; // 接收状态：0-空闲，1-接收高4位，2-接收低4位uint8_t temp_hex = 0; // 临时存储拼接的HEX值 ⑦ 编写中断服务函数解析 HEX 数据： 12345678910111213141516171819202122232425262728293031323334353637void USART1_IRQHandler(void) &#123; if (USART_GetITStatus(USART1, USART_IT_RXNE) != RESET) &#123; uint8_t data = USART_ReceiveData(USART1); uint8_t hex_val; // 字符转HEX值（0-9、A-F、a-f） if (data &gt;= &#x27;0&#x27; &amp;&amp; data &lt;= &#x27;9&#x27;) &#123; hex_val = data - &#x27;0&#x27;; &#125; else if (data &gt;= &#x27;A&#x27; &amp;&amp; data &lt;= &#x27;F&#x27;) &#123; hex_val = data - &#x27;A&#x27; + 10; &#125; else if (data &gt;= &#x27;a&#x27; &amp;&amp; data &lt;= &#x27;f&#x27;) &#123; hex_val = data - &#x27;a&#x27; + 10; &#125; else &#123; // 非HEX字符，重置状态（如空格、回车等作为分隔符） rx_state = 0; USART_ClearITPendingBit(USART1, USART_IT_RXNE); return; &#125; // 状态机解析HEX switch (rx_state) &#123; case 0: // 空闲状态，接收高4位 temp_hex = hex_val &lt;&lt; 4; rx_state = 1; break; case 1: // 接收低4位，拼接成完整字节 temp_hex |= hex_val; if (hex_rx_len &lt; HEX_BUF_SIZE) &#123; hex_rx_buf[hex_rx_len++] = temp_hex; &#125; rx_state = 0; // 解析完成，回到空闲 break; &#125; USART_ClearITPendingBit(USART1, USART_IT_RXNE); &#125;&#125; ⑧ 主函数中使用：发送测试 HEX 包，接收后回传： 1234567891011121314151617int main(void) &#123; USART1_Init(115200); // 初始化串口，波特率115200 // 测试发送：0x12 0x34 0xAB 0xCD uint8_t test_buf[] = &#123;0x12, 0x34, 0xAB, 0xCD&#125;; USART1_SendString((uint8_t*)&quot;Send: &quot;); USART1_SendHexPacket(test_buf, 4); while (1) &#123; // 接收处理：当收到数据时回传 if (hex_rx_len &gt; 0) &#123; USART1_SendString((uint8_t*)&quot;Received: &quot;); USART1_SendHexPacket(hex_rx_buf, hex_rx_len); hex_rx_len = 0; // 重置接收长度 &#125; &#125;&#125; 【案例】串口收发文本数据包① 使能相关时钟：开启 USART1、GPIOA、AFIO 时钟： 1234567#include &quot;stm32f10x.h&quot;#include &lt;string.h&gt;#define TEXT_BUF_SIZE 100 // 文本数据包最大长度void USART1_Init(uint32_t baudrate) &#123; RCC_APB2PeriphClockCmd(RCC_APB2Periph_USART1 | RCC_APB2Periph_GPIOA | RCC_APB2Periph_AFIO, ENABLE); ② 配置串口 GPIO：PA9（TX）复用推挽输出，PA10（RX）浮空输入： 1234567891011GPIO_InitTypeDef GPIO_InitStructure;// TX引脚（PA9）GPIO_InitStructure.GPIO_Pin = GPIO_Pin_9;GPIO_InitStructure.GPIO_Mode = GPIO_Mode_AF_PP;GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;GPIO_Init(GPIOA, &amp;GPIO_InitStructure);// RX引脚（PA10）GPIO_InitStructure.GPIO_Pin = GPIO_Pin_10;GPIO_InitStructure.GPIO_Mode = GPIO_Mode_IN_FLOATING;GPIO_Init(GPIOA, &amp;GPIO_InitStructure); ③ 初始化 USART 参数：设置波特率、8 位数据、1 位停止位、无校验： 12345678USART_InitTypeDef USART_InitStructure;USART_InitStructure.USART_BaudRate = baudrate;USART_InitStructure.USART_WordLength = USART_WordLength_8b;USART_InitStructure.USART_StopBits = USART_StopBits_1;USART_InitStructure.USART_Parity = USART_Parity_No;USART_InitStructure.USART_HardwareFlowControl = USART_HardwareFlowControl_None;USART_InitStructure.USART_Mode = USART_Mode_Tx | USART_Mode_Rx;USART_Init(USART1, &amp;USART_InitStructure); ④ 配置接收中断：使能 USART1 接收中断及 NVIC： 12345678910 NVIC_InitTypeDef NVIC_InitStructure; NVIC_InitStructure.NVIC_IRQChannel = USART1_IRQn; NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 1; NVIC_InitStructure.NVIC_IRQChannelSubPriority = 1; NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE; NVIC_Init(&amp;NVIC_InitStructure); USART_ITConfig(USART1, USART_IT_RXNE, ENABLE); USART_Cmd(USART1, ENABLE);&#125; ⑤ 实现文本发送函数：发送字符串（以 ‘\0’ 结尾）： 123456789101112131415161718// 发送单个字符void USART1_SendChar(char c) &#123; while (USART_GetFlagStatus(USART1, USART_FLAG_TXE) == RESET); USART_SendData(USART1, (uint8_t)c);&#125;// 发送文本字符串void USART1_SendText(const char *text) &#123; while (*text != &#x27;\0&#x27;) &#123; USART1_SendChar(*text++); &#125;&#125;// 发送文本数据包（带换行符）void USART1_SendTextPacket(const char *packet) &#123; USART1_SendText(packet); USART1_SendText(&quot;
&quot;); // 换行作为包结束标志&#125; ⑥ 定义文本接收缓冲区及标志： 123char text_rx_buf[TEXT_BUF_SIZE]; // 接收缓冲区uint16_t text_rx_len = 0; // 接收长度uint8_t text_rx_complete = 0; // 接收完成标志（收到换行符置1） ⑦ 编写中断服务函数接收文本： 123456789101112131415161718192021void USART1_IRQHandler(void) &#123; if (USART_GetITStatus(USART1, USART_IT_RXNE) != RESET) &#123; char data = (char)USART_ReceiveData(USART1); // 处理接收：遇到换行符结束，否则存入缓冲区 if (data == &#x27;
&#x27; || data == &#x27;&#x27;) &#123; if (text_rx_len &gt; 0) &#123; text_rx_buf[text_rx_len] = &#x27;\0&#x27;; // 字符串结尾 text_rx_complete = 1; // 置完成标志 text_rx_len = 0; // 重置长度 &#125; &#125; else &#123; // 缓冲区未满则存储字符 if (text_rx_len &lt; TEXT_BUF_SIZE - 1) &#123; text_rx_buf[text_rx_len++] = data; &#125; &#125; USART_ClearITPendingBit(USART1, USART_IT_RXNE); &#125;&#125; ⑧ 主函数中使用：发送文本包，接收后回传： 123456789101112131415int main(void) &#123; USART1_Init(115200); // 初始化串口，波特率115200 // 发送测试文本包 USART1_SendTextPacket(&quot;STM32 Serial Text Test&quot;); while (1) &#123; // 接收完成后回传 if (text_rx_complete) &#123; USART1_SendText(&quot;Received: &quot;); USART1_SendTextPacket(text_rx_buf); text_rx_complete = 0; // 清除标志 &#125; &#125;&#125; 二、I2C通讯2.1 简介 I2C总线(InterIC BUS)是由Philips公司开发的一种通用数据总线 两根通信线：SCL(SerialClock)、SDA(Serial Data) 同步，半双工 带数据应答 支持总线挂载多设备(一主多从、多主多从) 串口有USART硬件电路支持，异步通讯才比较稳定，但是软件模拟比较复杂。I2C因为是同步协议，软件模拟起来非常容易。使用同步时序就可以极大地降低单片机对硬件电路的依赖。即使没有硬件，也可以通过软件的引脚反转电平来实现时钟控制。而单片机去干别的事情的事就可以中断时钟线，这样设备也会停止接收，减少数据错误的可能。 异步通信就是省一根时钟线，对时间要求严格，对硬件电路的依赖比较严重。同步通讯则相反。 本教程主要任务：通过数据线，实现单片机外挂设备的控制功能，即实现读写外挂模块的寄存器。至少实现在指定位置写寄存器。 一般使用一主多从的模式：类似一个老师讲课，很多学生听课，学生只能被老师点名后才可以发言。 2.2 硬件电路 所有I2C设备的SCL连在一起，SDA连在一起 设备的SCL和SDA均要配置成开漏输出模式 SCL和SDA各添加一个上拉电阻，阻值一般为4.7K左右 主机对SCL线具有完全控制功能，空闲时候主机控制SDA，只有从机发送数据或从机应答的时候，主机才会转交SDA的控制权给从机。 为了防止电平没协调好而起冲突，****I2C设计禁止了所有设备输出强上拉的高电平，采用外置弱上拉电阻加开漏输出的电路结构 即只允许向下拉或者松手，有电阻弹簧会自动拉高（弱上拉)。 【好处】： ①完全杜绝了电源短路现象，保证电路的安全，防止同时被强拉或推的状态，即使多个根下拉杆子也没有问题。 ②避免了引脚模式的频繁切换，开漏加弱上拉的模式，同时兼具了输入和输出的功能。想输出就拉杆子放手，操作杆子变化，观察即可得到电平。因为开漏模式下，输出高电平就相当于断开引脚，所有在输入之前，可以直接输出高电平，不需要切换成输入模式。 ③模式会有一个线与的现象，只要有任意一个或多个设备输出了低电平，总线就处于低电平；所有设备输出高电平（放手）才处于高电平。I2C可以利用电路特征，执行多主机模式下的时钟同步和总线仲裁。 2.3 I2C时序基本单元 起始条件：SCL高电平期间，SDA从高电平切换到低电平 终止条件：SCL高电平期间，SDA从低电平切换到高电平 起始和终止条件都是由主机产生的，所有在总线空闲状态时，从机必须始终双手放开，不允许碰（如果触碰了就是多主机模式了)。 发送一个字节：SCL低电平期间，主机将数据位依次放到SDA线上（高位先行），然后释放SCL，从机将在SCL高电平期间读取数据位所以SCL高电平期间SDA不允许有数据变化，依次循环上述过程8次即可发送一个字节 一般上升沿时刻从机就已经读取完了。 接收一个字节：SCL低电平期间，从机将数据位依次放到SDA线上（高位先行），然后释放SCL，主机将在SCL高电平期间读取数据位所以SCL高电平期间SDA不允许有数据变化，依次循环上述过程8次即可接收一个字节（主机在接收之前，需要释放SDA，让发送从机控制） 从机的数据变换贴着SCL下降沿，因为接受到SCL上升沿后需要响应时间。 发送应答：主机在接收完一个字节之后，在下一个时钟发送一位数据，数据0表示应答，数据1表示非应答 接收应答：主机在发送完一个字节之后，在下一个时钟接收一位数据，判断从机是否应答，数据0表示应答，数据1表示非应答（主机在接收之前，需要释放SDA） 2.4 I2C时序2.4.1 指定地址写【过程说明】主机要确定访问的设备，就需要把每个从机都确定一个唯一的设备地址，从机设备地址就是名字。而主机发送前会叫一下这个名字，所有从机都会收到，但只有匹配的从机才进行响应读写操作。 【从机设备地址】在I2C标准里分为7位和10位地址，教程讲7位，因为比较简单和应用范围广。在每个设备出厂时候就会会被分配一个地址。具体可以在芯片手册里找到。相同型号的地址一般都是一样的地址。如果多个相同型号都挂在总线上。就需要用到地址中的可变部分来进行区分。 对于指定设备（Slave Address），在指定地址（Reg Address）下，写入指定数据（Data） 2.4.2 当前地址读 对于指定设备（Slave Address），在当前地址指针指示的地址下，读取从机数据（Data） 此时传输数据并没有指定写入从机的寄存器地址，因此需要用到地址指针。会自动增加地址写入。 2.4.3 指定地址读对于指定设备（Slave Address），在指定地址（Reg Address）下，读取从机数据（Data） 需要在指定地址写的从机地址时序部分后+当前地址读的时序，从而得到。 如果想发多个数据，只需要将数据部分重复即可，即在指定地址输入后，写入多个字节，地址会自增。注意这时候主机如果想要结束数据，就需要在最后一个数据结束后加上非应答，否则会让从机认为主机还需要数据，从机继续发生下一个数据，从而占据SDA，主机想产生停止条件就不能正常回答高电平了。 2.5 I2C外设简介 STM32内部集成了硬件I2C收发电路，可以由硬件自动执行时钟生成、起始终止条件生成、应答位收发、数据收发等功能，减轻CPU的负担 支持多主机模型 支持7位&#x2F;10位地址模式 支持不同的通讯速度，标准速度(高达100 kHz)，快速(高达400 kHz) 支持DMA 兼容SMBus（System Managerment Bus主要用于电源管理系统）协议 STM32F103C8T6 硬件I2C资源（硬件I2C受限于资源）：I2C1、I2C2 软件模拟I2C是非常常见的，但是作为一个协议标准，I2C通讯也是可以有硬件收发电路的。如果是简单应用，那么软件模拟会比较灵活，如果要求性能指标要求比较高，就考虑硬件I2C。本小结讲硬件STM32内部的I2C外设。 多主机模式下，两个主机同时通讯占用总线就要发起总线仲裁。可变多主机模式，所有设备一视同仁，谁想当主机谁就站出来。 关于I2C地址，可以通过修改低位可变地址部分来避免地址冲突，也可以另外再开辟I2C总线，比较容易解决。而STM32支持10位地址，1024种可能。在实现中，剩下的5位地址会用作标志位。 2.6 I2C框图 核心部分是数据寄存器和移位寄存器： 当我们需要发送数据时，可以把一个字节数据写到数据寄存器DR，这个数据寄存器的值就会进一步转到移位寄存器里，在移位的过程中，就可以把下一个数据放到数据寄存器里等着了，一但前一个数据移位完成，下一个数据就可以无缝衔接，继续发送。其中数据寄存器转到移位寄存器时候，就会置状态寄存器的TXE位为1，表示发送数据寄存器为空。 当我们需要接收时候，也是输入的数据一位一位的，从引脚移入到移位寄存器里，当一个字数据具收齐后，数据整体从移位寄存器转移到数据寄存器，同时置标志位RXNE，表示接收数据寄存器非空。这时候就可以把数据读出来了。 略。 2.7 I2C基本结构略。 2.8 硬件I2C操作流程参考序列图，才知道程序什么时候该做什么事情。手册给出了从机发送接收、主机发送接收，四个图，教程只关注主机发送和接收部分。 2.8.1 主机发送 7位地址起始条件后的一个字节是寻址，10位地址起始条件后的两个字节都是寻址。后续的数据可以由厂商规定。 STM32默认从模式，将硬件标志位置位，会因此转成主模式，表示有数据要发。之后软件检查EV5标志位（EVx标志位是组合了多个标志位的大标志位），看硬件是否都达到了想要的状态。 结合基本结构框图进行观看。 2.8.2 主机接收 2.9 软硬件波形对比 不标准的波形也不影响通讯。 手册，略。 【案例】硬件I2C读写① 使能相关时钟：开启 I2C1、GPIO（连接 SCL 和 SDA）时钟，I2C1 属于 APB1 总线，GPIOB 属于 APB2 总线： 123456789#include &quot;stm32f10x.h&quot;#define I2C_SCL_PIN GPIO_Pin_6 // GPIOB6作为SCL#define I2C_SDA_PIN GPIO_Pin_7 // GPIOB7作为SDA#define I2Cx I2C1void I2C_Config(void) &#123; RCC_APB1PeriphClockCmd(RCC_APB1Periph_I2C1, ENABLE); RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOB | RCC_APB2Periph_AFIO, ENABLE); ② 配置 I2C GPIO 引脚：SCL 和 SDA 需配置为复用开漏输出（I2C 总线要求）： 12345GPIO_InitTypeDef GPIO_InitStructure;GPIO_InitStructure.GPIO_Pin = I2C_SCL_PIN | I2C_SDA_PIN;GPIO_InitStructure.GPIO_Mode = GPIO_Mode_AF_OD; // 复用开漏输出GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;GPIO_Init(GPIOB, &amp;GPIO_InitStructure); ③ 初始化 I2C 参数：设置时钟频率（如 100kHz 标准模式）、地址模式等： 12345678910I2C_InitTypeDef I2C_InitStructure;I2C_InitStructure.I2C_Mode = I2C_Mode_I2C; // I2C模式I2C_InitStructure.I2C_DutyCycle = I2C_DutyCycle_2; // 占空比2:1I2C_InitStructure.I2C_OwnAddress1 = 0x00; // 自身地址（从机模式用，主机模式可不设）I2C_InitStructure.I2C_Ack = I2C_Ack_Enable; // 使能应答I2C_InitStructure.I2C_AcknowledgedAddress = I2C_AcknowledgedAddress_7bit; // 7位地址模式I2C_InitStructure.I2C_ClockSpeed = 100000; // 时钟频率100kHzI2C_Init(I2Cx, &amp;I2C_InitStructure);I2C_Cmd(I2Cx, ENABLE); // 使能I2C ④ 实现 I2C 起始信号函数： 1234567// 发送起始信号，返回0表示成功uint8_t I2C_Start(void) &#123; I2C_GenerateSTART(I2Cx, ENABLE); // 等待起始信号发送完成 while (!I2C_CheckEvent(I2Cx, I2C_EVENT_MASTER_MODE_SELECT)); return 0;&#125; ⑤ 实现 I2C 发送设备地址函数（含读写位）： 12345678910111213141516// 发送设备地址+读写位（read=1读，0写），返回0表示成功uint8_t I2C_SendAddr(uint8_t addr, uint8_t read) &#123; addr &lt;&lt;= 1; if (read) addr |= 0x01; // 读操作 else addr &amp;= ~0x01; // 写操作 I2C_Send7bitAddress(I2Cx, addr, (read ? I2C_Direction_Receiver : I2C_Direction_Transmitter)); // 等待地址应答 if (read) &#123; while (!I2C_CheckEvent(I2Cx, I2C_EVENT_MASTER_RECEIVER_MODE_SELECTED)); &#125; else &#123; while (!I2C_CheckEvent(I2Cx, I2C_EVENT_MASTER_TRANSMITTER_MODE_SELECTED)); &#125; return 0;&#125; ⑥ 实现 I2C 发送数据函数： 1234567// 发送单个字节数据，返回0表示成功uint8_t I2C_SendData(uint8_t data) &#123; I2C_SendData(I2Cx, data); // 等待数据发送完成 while (!I2C_CheckEvent(I2Cx, I2C_EVENT_MASTER_BYTE_TRANSMITTED)); return 0;&#125; ⑦ 实现 I2C 接收数据函数（带应答控制）： 1234567891011121314151617// 接收数据，last=1表示最后一个字节（不应答），返回接收值uint8_t I2C_ReceiveData(uint8_t last) &#123; if (last) &#123; I2C_AcknowledgeConfig(I2Cx, DISABLE); // 最后一个字节不应答 I2C_NACKPositionConfig(I2Cx, I2C_NACKPosition_Current); &#125; // 等待数据接收完成 while (!I2C_CheckEvent(I2Cx, I2C_EVENT_MASTER_BYTE_RECEIVED)); uint8_t data = I2C_ReceiveData(I2Cx); if (last) &#123; I2C_AcknowledgeConfig(I2Cx, ENABLE); // 恢复应答使能 &#125; return data;&#125; ⑧ 实现 I2C 停止信号函数： 123void I2C_Stop(void) &#123; I2C_GenerateSTOP(I2Cx, ENABLE);&#125; ⑨ 封装 I2C 写设备寄存器函数： 123456789// 向设备addr的reg寄存器写入datauint8_t I2C_WriteReg(uint8_t addr, uint8_t reg, uint8_t data) &#123; I2C_Start(); I2C_SendAddr(addr, 0); // 写设备地址 I2C_SendData(reg); // 发送寄存器地址 I2C_SendData(data); // 发送数据 I2C_Stop(); return 0;&#125; ⑩ 封装 I2C 读设备寄存器函数： 12345678910111213// 从设备addr的reg寄存器读取数据，返回读取值uint8_t I2C_ReadReg(uint8_t addr, uint8_t reg) &#123; uint8_t data; I2C_Start(); I2C_SendAddr(addr, 0); // 写设备地址（用于发送寄存器地址） I2C_SendData(reg); // 发送寄存器地址 I2C_Start(); // 重复起始信号 I2C_SendAddr(addr, 1); // 读设备地址 data = I2C_ReceiveData(1); // 读数据（最后一个字节） I2C_Stop(); return data;&#125; ⑪ 主函数中使用示例（读写某 I2C 设备寄存器）： 12345678910111213int main(void) &#123; I2C_Config(); // 初始化I2C // 向设备0x48的0x00寄存器写入0x55 I2C_WriteReg(0x48, 0x00, 0x55); // 从设备0x48的0x00寄存器读取数据 uint8_t val = I2C_ReadReg(0x48, 0x00); while (1) &#123; // 循环执行其他任务 &#125;&#125; 三、SPI通讯3.1 简介 SPI（Serial Peripheral Interface）是由Motorola公司开发的一种通用数据总线 四根通信线：SCK（Serial Clock）、MOSI（Master Output Slave Input）、MISO（Master Input Slave Output）、SS（Slave Select）。名称会有不同，注意对照芯片手册即可。 同步，全双工 支持总线挂载多设备（仅一主多从），会有多根SS线 比较之前学习的I2C还是比较复杂的，地址限制下多设备都只需要两根线。但是其通讯线高电平驱动能力比较弱，这会导致上升沿的过程耗时长，限制通讯速度100、400KHz。相对于I2C，SPI的优缺点： ①SPI协议并没有严格规定最大传输速度，其取决于芯片厂商需求。 ②SPI比较简单，没有I2C那么多功能。 ③全双工，SPI硬件开销大，通讯过程中经常会有资源库浪费现象。有钱！就是要快速。 3.2 硬件电路 所有SPI设备的SCK、MOSI、MISO分别连在一起 SCK：时钟线完全由主机掌控，主机输出，从机输入。 MOSI：主机输出，从机输入 MISO：主机输入（看图中箭头），从机输出 主机另外引出多条SS控制线，分别接到各从机的SS引脚 输出引脚配置为推挽输出，输入引脚配置为浮空或上拉输入 SPI的输入输出引脚是固定的，基本不会出现冲突，因此可以使用推挽输出。但SPI仍有可能在MISO线上多个从机推挽输出造成冲突，因此SPI规定从机未被选中时候的MISO引脚必须为高阻态，当然写主机程序不需要关注从机这个问题。 3.3 移位示意图移位寄存器随着SCK的频率触发移位，会将箭头方向移出去的一位放到引脚上。在SCK频率触发的间隔，主机和从机都进行数据采集，获取移除位所在的引脚的电平存放到各自箭头方向连接的寄存器上。 多次后就完成了一个字节的数据交换。只收或只发的情况下，只需要忽略掉发送或者接收信号即可。 3.4 SPI时序基本单元 起始条件：SS从高电平切换到低电平 终止条件：SS从低电平切换到高电平 交换数据过程，SPI并没偶有规定在SCK的什么时候进行移位，给了开发者配置的选择，兼容更多芯片。有两个可以配置的位，提高协议兼容性，产生了如下四种模式：****模式虽然多，功能相似，只学习一种即可。 【交换一个字节（模式0）】 （时钟极性）CPOL&#x3D;0：空闲状态时，SCK为低电平 （时钟相位）CPHA&#x3D;0：SCK第一个边沿移入数据，第二个边沿移出数据 MISO不发送数据时候为高阻态（中间线)，只要SS不置高，可以一致重复交换数据。 【交换一个字节（模式1）】****（常用、高速） CPOL&#x3D;0：空闲状态时，SCK为低电平 CPHA&#x3D;1：SCK第一个边沿移出数据，第二个边沿移入数据 【交换一个字节（模式2）】 CPOL&#x3D;1：空闲状态时，SCK为高电平 CPHA&#x3D;0：SCK第一个边沿移入数据，第二个边沿移出数据 【交换一个字节（模式3）】 CPOL&#x3D;1：空闲状态时，SCK为高电平 CPHA&#x3D;1：SCK第一个边沿移出数据，第二个边沿移入数据 3.5 SPI时序3.5.1 发送指令在I2C中使用的是读写寄存器的模型（地址+数据），而SPI通常采用指令码加读写数据的模型（指令码+数据）。 3.5.2 指定地址写向SS指定的设备，发送写指令（0x02），随后在指定地址（**Address[23:0]**）下，写入指定数据（Data） W25Q64规定写指令之后的字节定义为地址高位。 3.5.3 指定地址读向SS指定的设备，发送读指令（0x03），随后在指定地址（Address[23:0]）下，读取从机数据（Data） 因为要读取数据，所以在指令码（0x03）+地址（0x123456）之后随便给从机一个数据，一般给0xFF，这时从机就会把0x123456地址下的数据通过MISO发给主机。如果主机继续发送数据，从机地址指针自动+1，就可以获取下一个地址的数据，实现多个地址接收。 3.6 SPI外设简介 STM32内部集成了硬件SPI收发电路，可以由硬件自动执行时钟生成、数据收发等功能，减轻CPU的负担 可配置8位&#x2F;16位数据帧（用得少）、高位先行（SPI基本都是）&#x2F;低位先行（串口是低位先行） 时钟频率： fPCLK &#x2F; (2, 4, 8, 16, 32, 64, 128, 256) 支持多主机模型、主或从操作 可精简为半双工&#x2F;单工通信 支持DMA 兼容I2S协议（音频传输协议） STM32F103C8T6 硬件SPI资源：SPI1（72MHz）、SPI2（36MHz） 3.7 SPI框图 MOSI和MISO引脚交叉连接部分，用于引脚变化的，用于主从机切换，只当主机时就不用管了。其中箭头错误已更改。移位寄存器参考先前的移位示意图的内容。 略 3.8 SPI基本结构注：阅读手册时候，手册不同部分的名词翻译会有略微区别，但指代一致，注意理解。 注意TDR、TXE、RDR、RXNE等标志位。框图缺少SS，这个引脚使用普通GPIO来模拟即可。 3.9 主模式传输操作3.9.1 全双工连续传输 3.9.2 非连续传输正常考虑这个传输方式。 【区别】：当TXE置1后，第一个字节写入TDR，等待传输第一个字节时序结束，即接收完成，这时RXNE会置1，然后把第一个接受到的数据从RDR读出来（较晚写入的原因），之后再写入下一个字节数据。 【总结】： ①等待TXE置1。②写入TDR数据。③等待RXNE置1。④读取RDR数据 继续循环等待TXE…再写入TDR数据…..将这4步骤封装成一个函数，掉一次写入一个字节，实现起来就非常简单。 【缺点】：在TXE置1的位置，没有及时把下一个数据写入TDR等候着，当读取数据完成后，下一个字节数据还没有传输，就会使得字节与字节之间有等待间隙。慢的时钟速度下不明显，但一快起来就明显拖慢。 因此在追求最高性能的，还是使用连续传输操作逻辑或者进一步采用DMA转运。 3.10 软硬件波形对比 手册，略 【案例】硬件SPI读写W25Q64① 使能相关时钟：开启 SPI1、GPIO（SCK、MOSI、MISO、CS）时钟，SPI1 属于 APB2 总线，GPIOA 属于 APB2 总线： 1234567891011#include &quot;stm32f10x.h&quot;// W25Q64引脚定义（SPI1）#define W25Q_SCK_PIN GPIO_Pin_5 // PA5#define W25Q_MOSI_PIN GPIO_Pin_7 // PA7#define W25Q_MISO_PIN GPIO_Pin_6 // PA6#define W25Q_CS_PIN GPIO_Pin_4 // PA4（片选）#define W25Q_SPI SPI1void W25Q64_Init(void) &#123; RCC_APB2PeriphClockCmd(RCC_APB2Periph_SPI1 | RCC_APB2Periph_GPIOA, ENABLE); ② 配置 SPI GPIO 引脚：SCK、MOSI 为复用推挽输出，MISO 为浮空输入，CS 为推挽输出： 1234567891011121314151617GPIO_InitTypeDef GPIO_InitStructure;// SCK、MOSI：复用推挽输出GPIO_InitStructure.GPIO_Pin = W25Q_SCK_PIN | W25Q_MOSI_PIN;GPIO_InitStructure.GPIO_Mode = GPIO_Mode_AF_PP;GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;GPIO_Init(GPIOA, &amp;GPIO_InitStructure);// MISO：浮空输入GPIO_InitStructure.GPIO_Pin = W25Q_MISO_PIN;GPIO_InitStructure.GPIO_Mode = GPIO_Mode_IN_FLOATING;GPIO_Init(GPIOA, &amp;GPIO_InitStructure);// CS：推挽输出（手动控制片选）GPIO_InitStructure.GPIO_Pin = W25Q_CS_PIN;GPIO_InitStructure.GPIO_Mode = GPIO_Mode_Out_PP;GPIO_SetBits(GPIOA, W25Q_CS_PIN); // 初始拉高（未选中）GPIO_Init(GPIOA, &amp;GPIO_InitStructure); ③ 初始化 SPI 参数：设置为主机模式，时钟极性 &#x2F; 相位（CPOL&#x3D;1，CPHA&#x3D;1，匹配 W25Q64）： 12345678910111213SPI_InitTypeDef SPI_InitStructure;SPI_InitStructure.SPI_Direction = SPI_Direction_2Line_FullDuplex; // 全双工SPI_InitStructure.SPI_Mode = SPI_Mode_Master; // 主机模式SPI_InitStructure.SPI_DataSize = SPI_DataSize_8b; // 8位数据SPI_InitStructure.SPI_CPOL = SPI_CPOL_High; // 时钟极性：高电平空闲SPI_InitStructure.SPI_CPHA = SPI_CPHA_2Edge; // 时钟相位：第二个边沿采样SPI_InitStructure.SPI_NSS = SPI_NSS_Soft; // 软件控制片选SPI_InitStructure.SPI_BaudRatePrescaler = SPI_BaudRatePrescaler_2; // 分频（72MHz/2=36MHz）SPI_InitStructure.SPI_FirstBit = SPI_FirstBit_MSB; // 高位在前SPI_InitStructure.SPI_CRCPolynomial = 7; // CRC多项式（不使用CRC）SPI_Init(W25Q_SPI, &amp;SPI_InitStructure);SPI_Cmd(W25Q_SPI, ENABLE); // 使能SPI ④ 实现 SPI 单字节收发函数： 12345678910// SPI发送并接收一个字节（全双工）uint8_t SPI_WriteReadByte(uint8_t tx_data) &#123; // 等待发送缓冲区为空 while (SPI_I2S_GetFlagStatus(W25Q_SPI, SPI_I2S_FLAG_TXE) == RESET); SPI_I2S_SendData(W25Q_SPI, tx_data); // 等待接收缓冲区非空 while (SPI_I2S_GetFlagStatus(W25Q_SPI, SPI_I2S_FLAG_RXNE) == RESET); return SPI_I2S_ReceiveData(W25Q_SPI);&#125; ⑤ 实现 W25Q64 基础控制函数（片选、唤醒、擦除等）： 12345678910111213141516171819202122232425262728293031323334353637// 选中W25Q64void W25Q_Select(void) &#123; GPIO_ResetBits(GPIOA, W25Q_CS_PIN);&#125;// 取消选中W25Q64void W25Q_Deselect(void) &#123; GPIO_SetBits(GPIOA, W25Q_CS_PIN);&#125;// 读取设备ID（验证通信）uint16_t W25Q_ReadID(void) &#123; uint16_t id; W25Q_Select(); SPI_WriteReadByte(0x90); // 读ID命令 SPI_WriteReadByte(0x00); // 地址高位 SPI_WriteReadByte(0x00); // 地址中位 SPI_WriteReadByte(0x00); // 地址低位 id = (SPI_WriteReadByte(0xFF) &lt;&lt; 8) | SPI_WriteReadByte(0xFF); // 读取ID W25Q_Deselect(); return id; // W25Q64的ID应为0xEF16&#125;// 写使能void W25Q_WriteEnable(void) &#123; W25Q_Select(); SPI_WriteReadByte(0x06); // 写使能命令 W25Q_Deselect();&#125;// 等待忙状态结束void W25Q_WaitBusy(void) &#123; W25Q_Select(); SPI_WriteReadByte(0x05); // 读状态寄存器命令 while ((SPI_WriteReadByte(0xFF) &amp; 0x01) == 0x01); // 忙标志位为1时等待 W25Q_Deselect();&#125; ⑥ 实现扇区擦除函数（W25Q64 最小擦除单位为 4KB 扇区）： 1234567891011121314void W25Q_EraseSector(uint32_t addr) &#123; W25Q_WriteEnable(); W25Q_WaitBusy(); W25Q_Select(); SPI_WriteReadByte(0x20); // 扇区擦除命令 // 发送3字节地址（24位） SPI_WriteReadByte((addr &gt;&gt; 16) &amp; 0xFF); SPI_WriteReadByte((addr &gt;&gt; 8) &amp; 0xFF); SPI_WriteReadByte(addr &amp; 0xFF); W25Q_Deselect(); W25Q_WaitBusy(); // 等待擦除完成（约400ms）&#125; ⑦ 实现页写入函数（W25Q64 一页为 256 字节）： 1234567891011121314151617181920void W25Q_WritePage(uint32_t addr, uint8_t *data, uint16_t len) &#123; if (len &gt; 256) len = 256; // 超过一页限制 W25Q_WriteEnable(); W25Q_WaitBusy(); W25Q_Select(); SPI_WriteReadByte(0x02); // 页写入命令 // 发送3字节地址 SPI_WriteReadByte((addr &gt;&gt; 16) &amp; 0xFF); SPI_WriteReadByte((addr &gt;&gt; 8) &amp; 0xFF); SPI_WriteReadByte(addr &amp; 0xFF); // 写入数据 for (uint16_t i = 0; i &lt; len; i++) &#123; SPI_WriteReadByte(data[i]); &#125; W25Q_Deselect(); W25Q_WaitBusy();&#125; ⑧ 实现连续读取函数： 12345678910111213void W25Q_ReadData(uint32_t addr, uint8_t *data, uint16_t len) &#123; W25Q_Select(); SPI_WriteReadByte(0x03); // 读数据命令 // 发送3字节地址 SPI_WriteReadByte((addr &gt;&gt; 16) &amp; 0xFF); SPI_WriteReadByte((addr &gt;&gt; 8) &amp; 0xFF); SPI_WriteReadByte(addr &amp; 0xFF); // 读取数据 for (uint16_t i = 0; i &lt; len; i++) &#123; data[i] = SPI_WriteReadByte(0xFF); &#125; W25Q_Deselect();&#125; ⑨ 主函数使用示例（擦除→写入→读取验证）： 123456789101112131415161718192021int main(void) &#123; uint8_t w_data[5] = &#123;0x11, 0x22, 0x33, 0x44, 0x55&#125;; uint8_t r_data[5]; uint16_t id; W25Q64_Init(); id = W25Q_ReadID(); // 读取ID，验证是否为0xEF16 // 擦除0x00000地址的扇区 W25Q_EraseSector(0x00000); // 向0x00000地址写入5字节数据 W25Q_WritePage(0x00000, w_data, 5); // 从0x00000地址读取5字节数据 W25Q_ReadData(0x00000, r_data, 5); while (1) &#123; // 循环执行 &#125;&#125; 笔记部分引用菜工啊潜 STM32标准库系列文章 STM32标准库笔记（一）-准备、GPIO、中断 | 超小韓の个人博客 STM32标准库笔记（二）-PWM、ADC、DMA | 超小韓の个人博客 STM32标准库笔记（三）-USART、I2C、SPI | 超小韓の个人博客 STM32标准库笔记（四）-BKP、RTC、PWR、WDG、FLASH | 超小韓の个人博客

一、标识符 第一个字符必须以字母（a-z, A-Z）或下划线 _ 。 标识符的其他的部分由字母、数字和下划线组成。 标识符对大小写敏感，count 和 Count 是不同的标识符。 标识符对长度无硬性限制，但建议保持简洁（一般不超过 20 个字符）。 禁止使用保留关键字，如 if、for、class 等不能作为标识符。 二、关键字 类别 关键字 说明 逻辑值 True 布尔真值 False 布尔假值 None 表示空值或无值 逻辑运算 and 逻辑与运算 or 逻辑或运算 not 逻辑非运算 条件控制 if 条件判断语句 elif 否则如果（else if 的缩写） else 否则分支 循环控制 for 迭代循环 while 条件循环 break 跳出循环 continue 跳过当前循环的剩余部分，进入下一次迭代 异常处理 try 尝试执行代码块 except 捕获异常 finally 无论是否发生异常都会执行的代码块 raise 抛出异常 函数定义 def 定义函数 return 从函数返回值 lambda 创建匿名函数 类与对象 class 定义类 del 删除对象引用 模块导入 import 导入模块 from 从模块导入特定部分 as 为导入的模块或对象创建别名 作用域 global 声明全局变量 nonlocal 声明非局部变量（用于嵌套函数） 异步编程 async 声明异步函数 await 等待异步操作完成 其他 assert 断言，用于测试条件是否为真 in 检查成员关系 is 检查对象身份（是否是同一个对象） pass 空语句，用于占位 with 上下文管理器，用于资源管理 yield 从生成器函数返回值 更多 Python 保留关键字参考：https://www.runoob.com/python3/python3-keyword.html。 三、注释Python 中单行注释以 *#* 开头 # 符号后面的所有文本都被视为注释，不会被解释器执行。 在 Python中，多行字符串（由三个单引号 ‘’’ 或三个双引号 “”” 包围的文本块）在某些情况下可以被视为一种实现多行注释的技巧。 多行注释用三个单引号 ‘’’ 或者三个双引号 &quot;“” 将注释括起来 嵌套多行注释会导致语法错误 注释形式 1234567891011121314# 第一个注释# 第二个注释 &#x27;&#x27;&#x27;第三注释第四注释&#x27;&#x27;&#x27; &quot;&quot;&quot;第五注释第六注释&quot;&quot;&quot;print (&quot;Hello, Python!&quot;) 四、行与缩进python最具特色的就是使用缩进来表示代码块，不需要使用大括号 {} 。 缩进的空格数是可变的，但是同一个代码块的语句必须包含相同的缩进空格数。实例如下： 1234if True: print (&quot;True&quot;)else: print (&quot;False&quot;) 4.1多行语句Python 通常是一行写完一条语句，但如果语句很长，我们可以使用反斜杠 ** 来实现多行语句，例如： 123total = item_one + \ item_two + \ item_three 在 [], {}, 或 () 中的多行语句，不需要使用反斜杠 ****，例如： 12total = [&#x27;item_one&#x27;, &#x27;item_two&#x27;, &#x27;item_three&#x27;, &#x27;item_four&#x27;, &#x27;item_five&#x27;] 五、数字(Number)类型Python 数字数据类型用于存储数值。 数据类型是不允许改变的，这就意味着如果改变数字数据类型的值，将重新分配内存空间。 以下实例在变量赋值时 Number 对象将被创建： 12var1 = 1var2 = 10 您也可以使用del语句删除一些数字对象的引用。 del语句的语法是： 1del var1[,var2[,var3[....,varN]]] 您可以通过使用del语句删除单个或多个对象的引用，例如： 12del vardel var_a, var_b Python 支持三种不同的数值类型： 整型(int) - 通常被称为是整型或整数，是正或负整数，不带小数点。Python3 整型是没有限制大小的，可以当作 Long 类型使用，所以 Python3 没有 Python2 的 Long 类型。布尔(bool)是整型的子类型。 浮点型(float) - 浮点型由整数部分与小数部分组成，浮点型也可以使用科学计数法表示（2.5e2 &#x3D; 2.5 x 102 &#x3D; 250） 复数( (complex)) - 复数由实数部分和虚数部分构成，可以用a + bj,或者complex(a,b)表示， 复数的实部a和虚部b都是浮点型。 我们可以使用十六进制和八进制来代表整数： 1234567&gt;&gt;&gt; number = 0xA0F # 十六进制&gt;&gt;&gt; number2575&gt;&gt;&gt; number=0o37 # 八进制&gt;&gt;&gt; number31 Python支持复数，复数由实数部分和虚数部分构成，可以用a + bj,或者complex(a,b)表示， 复数的实部a和虚部b都是浮点型。 5.1Python 数字类型转换有时候，我们需要对数据内置的类型进行转换，数据类型的转换，你只需要将数据类型作为函数名即可。 int(x) 将x转换为一个整数。 float(x) 将x转换到一个浮点数。 complex(x) 将x转换到一个复数，实数部分为 x，虚数部分为 0。 complex(x, y) 将 x 和 y 转换到一个复数，实数部分为 x，虚数部分为 y。x 和 y 是数字表达式。 以下实例将浮点数变量 a 转换为整数： 123&gt;&gt;&gt; a = 1.0&gt;&gt;&gt; int(a)1 5.2Python 数字运算Python 解释器可以作为一个简单的计算器，您可以在解释器里输入一个表达式，它将输出表达式的值。 表达式的语法很直白： +, -, ***** 和 &#x2F;, 和其它语言（如Pascal或C）里一样。例如： 12345678&gt;&gt;&gt; 2 + 24&gt;&gt;&gt; 50 - 5*620&gt;&gt;&gt; (50 - 5*6) / 45.0&gt;&gt;&gt; 8 / 5 # 总是返回一个浮点数1.6 注意：在不同的机器上浮点运算的结果可能会不一样。 在整数除法中，除法 &#x2F; 总是返回一个浮点数，如果只想得到整数的结果，丢弃可能的分数部分，可以使用运算符 &#x2F;&#x2F; ： 123456789&gt;&gt;&gt; 17 / 3 # 整数除法返回浮点型5.666666666666667&gt;&gt;&gt;&gt;&gt;&gt; 17 // 3 # 整数除法返回向下取整后的结果5&gt;&gt;&gt; 17 % 3 # ％操作符返回除法的余数2&gt;&gt;&gt; 5 * 3 + 2 17 注意：&#x2F;&#x2F; 得到的并不一定是整数类型的数，它与分母分子的数据类型有关系。 1234567&gt;&gt;&gt; 7//23&gt;&gt;&gt; 7.0//23.0&gt;&gt;&gt; 7//2.03.0&gt;&gt;&gt; 等号 &#x3D; 用于给变量赋值。赋值之后，除了下一个提示符，解释器不会显示任何结果。 1234&gt;&gt;&gt; width = 20&gt;&gt;&gt; height = 5*9&gt;&gt;&gt; width * height900 Python 可以使用 ** 操作来进行幂运算： 1234&gt;&gt;&gt; 5 ** 2 # 5 的平方25&gt;&gt;&gt; 2 ** 7 # 2的7次方128 变量在使用前必须先”定义”（即赋予变量一个值），否则会出现错误： 1234&gt;&gt;&gt; n # 尝试访问一个未定义的变量Traceback (most recent call last): File &quot;&lt;stdin&gt;&quot;, line 1, in &lt;module&gt;NameError: name &#x27;n&#x27; is not defined 不同类型的数混合运算时会将整数转换为浮点数： 1234&gt;&gt;&gt; 3 * 3.75 / 1.57.5&gt;&gt;&gt; 7.0 / 23.5 在交互模式中，最后被输出的表达式结果被赋值给变量 _ 。例如： 12345678&gt;&gt;&gt; tax = 12.5 / 100&gt;&gt;&gt; price = 100.50&gt;&gt;&gt; price * tax12.5625&gt;&gt;&gt; price + _113.0625&gt;&gt;&gt; round(_, 2)113.06 此处， _ 变量应被用户视为只读变量。 5.3数学函数 函数 返回值 ( 描述 ) abs(x) 返回数字的绝对值，如abs(-10) 返回 10 ceil(x) 返回数字的上入整数，如math.ceil(4.1) 返回 5 cmp(x, y) 如果 x &lt; y 返回 -1, 如果 x &#x3D;&#x3D; y 返回 0, 如果 x &gt; y 返回 1。 Python 3 已废弃，使用 (x&gt;y)-(x&lt;y) 替换。 exp(x) 返回e的x次幂(ex),如math.exp(1) 返回2.718281828459045 fabs(x) 以浮点数形式返回数字的绝对值，如math.fabs(-10) 返回10.0 floor(x) 返回数字的下舍整数，如math.floor(4.9)返回 4 log(x) 如math.log(math.e)返回1.0,math.log(100,10)返回2.0 log10(x) 返回以10为基数的x的对数，如math.log10(100)返回 2.0 max(x1, x2,…) 返回给定参数的最大值，参数可以为序列。 min(x1, x2,…) 返回给定参数的最小值，参数可以为序列。 modf(x) 返回x的整数部分与小数部分，两部分的数值符号与x相同，整数部分以浮点型表示。 pow(x, y) x**y 运算后的值。 [round(x ,n]) 返回浮点数 x 的四舍五入值，如给出 n 值，则代表舍入到小数点后的位数。其实准确的说是保留值将保留到离上一位更近的一端。 sqrt(x) 返回数字x的平方根。 5.4随机数函数随机数可以用于数学，游戏，安全等领域中，还经常被嵌入到算法中，用以提高算法效率，并提高程序的安全性。 Python包含以下常用随机数函数： 函数 描述 choice(seq) 从序列的元素中随机挑选一个元素，比如random.choice(range(10))，从0到9中随机挑选一个整数。 [randrange (start,] stop [,step]) 从指定范围内，按指定基数递增的集合中获取一个随机数，基数默认值为 1 random() 随机生成下一个实数，它在[0,1)范围内。 [seed(x]) 改变随机数生成器的种子seed。如果你不了解其原理，你不必特别去设定seed，Python会帮你选择seed。 shuffle(lst) 将序列的所有元素随机排序 uniform(x, y) 随机生成下一个实数，它在[x,y]范围内。 5.5三角函数Python包括以下三角函数： 函数 描述 acos(x) 返回x的反余弦弧度值。 asin(x) 返回x的反正弦弧度值。 atan(x) 返回x的反正切弧度值。 atan2(y, x) 返回给定的 X 及 Y 坐标值的反正切值。 cos(x) 返回x的弧度的余弦值。 hypot(x, y) 返回欧几里德范数 sqrt(xx + yy)。 sin(x) 返回的x弧度的正弦值。 tan(x) 返回x弧度的正切值。 degrees(x) 将弧度转换为角度,如degrees(math.pi&#x2F;2) ， 返回90.0 radians(x) 将角度转换为弧度 5.6数学常量 常量 描述 pi 数学常量 pi（圆周率，一般以π来表示） e 数学常量 e，e即自然常数（自然常数）。 六、字符串(String) Python 中单引号 ‘ 和双引号 “ 使用完全相同。 使用三引号(‘’’ 或 “””)可以指定一个多行字符串。 转义符 ****。 反斜杠可以用来转义，使用 r 可以让反斜杠不发生转义。 如 r”this is a line with 
” 则 
